def prose_clean(s):
 return re.sub(r"[A-Za-z]{8,}",lambda m:PROSE_FIXES.get(m.group(0),m.group(0)),s)
for r in rows:
 for key in ["reasoning","scope","reviewNotice","referenceAnswer"]:
  if key in r:r[key]=prose_clean(r[key])
 r["assumptions"]=[prose_clean(v) for v in r["assumptions"]]
 for f in r["parts"]:
  for key in ["label","explanation"]:f[key]=prose_clean(f[key])
  if f["type"]=="choice":
   f["answer"]=prose_clean(f["answer"]);f["options"]=[prose_clean(v) for v in f["options"]]

FINAL_PROSE_REPAIRS={'capacitance s': 'capacitances', 'inductance s': 'inductances', 'Integrates in': 'Integrate sin', 'of s in': 'of sin', 'Left ward': 'Leftward', 'left ward': 'leftward', 'Right ward': 'Rightward', 'right ward': 'rightward', 'gyro magnetic': 'gyromagnetic', 'V rms': 'Vrms', 'I rms': 'Irms', 'I DC': 'I_DC', 'forml': 'for ml', 'ofthe': 'of the', 'butits': 'but its', 'andf': 'and f', 'hencec': 'hence c', 'soa': 'so a'}
def repair(s):
 for a,b in FINAL_PROSE_REPAIRS.items():s=s.replace(a,b)
 return s
for r in rows:
 for key in ["reasoning","scope","reviewNotice","referenceAnswer"]:
  if key in r:r[key]=repair(r[key])
 r["assumptions"]=[repair(v) for v in r["assumptions"]]
 for f in r["parts"]:
  for key in ["label","explanation"]:f[key]=repair(f[key])
  f["label"]=re.sub(r"([A-Za-z]{2,})([0-9])",r"\1 \2",f["label"])
  if f["type"]=="choice":
   f["answer"]=repair(f["answer"]);f["options"]=[repair(v) for v in f["options"]]
(HERE/'ch32.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
print('Chapter32',len(rows),'records',sum(len(r['parts']) for r in rows),'fields')
